solution.code:
package main

import (
	"fmt"
	"runtime"
)

func main() {
	// runtime exposes build/target info at no cost
	fmt.Printf("%s/%s on %s\n", runtime.GOOS, runtime.GOARCH, runtime.Version())
}

package main

import (
	"fmt"
	"os"
)

func main() {
	// LookupEnv reports whether the variable was set at all.
	name, ok := os.LookupEnv("NAME")
	if !ok || name == "" {
		fmt.Fprintln(os.Stderr, "NAME is required")
		os.Exit(1) // non-zero status signals failure to the caller
	}
	fmt.Printf("Hello, %s!\n", name)
}
